const items = $input.all();
const form = items[0].json;

const category = form['Product Category'] || form.category || 'Area Rug';
const focus = form['Focus Area'] || form.focus || '';

// ── Decode uploaded HTML files ──────────────────────────────────────────────
let p2Content = '';
if (form['P2 Market Analysis Report']) {
  const p2Data = form['P2 Market Analysis Report'];
  if (typeof p2Data === 'string') { p2Content = p2Data; }
  else if (p2Data.data) { p2Content = Buffer.from(p2Data.data, 'base64').toString('utf8'); }
}

let p3Content = '';
if (form['P3 Competitor Analysis Report']) {
  const p3Data = form['P3 Competitor Analysis Report'];
  if (typeof p3Data === 'string') { p3Content = p3Data; }
  else if (p3Data.data) { p3Content = Buffer.from(p3Data.data, 'base64').toString('utf8'); }
}

// ── Strip HTML tags ─────────────────────────────────────────────────────────
const stripHtml = (html) => html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const p2Text = stripHtml(p2Content);
const p3Text = stripHtml(p3Content);

// ── INPUT VALIDATION ────────────────────────────────────────────────────────
const validationErrors = [];
if (!p2Content || p2Text.length < 200) validationErrors.push('P2 Market Analysis Report appears empty or too short.');
if (!p3Content || p3Text.length < 200) validationErrors.push('P3 Competitor Analysis Report appears empty or too short.');
if (!p2Text.toLowerCase().includes('micro') && !p2Text.toLowerCase().includes('segment'))
  validationErrors.push('P2 report does not appear to contain micro-segment data.');
if (!p3Text.toLowerCase().includes('wayfair') || !p3Text.toLowerCase().includes('amazon'))
  validationErrors.push('P3 report does not appear to contain competitor comparison data.');

// ── PARSE P02 MICRO-SEGMENTS ─────────────────────────────────────────────────
// Strategy: find the Micro-Segments block and extract each segment's fields.
// The P02 HTML renders segments as: [Name] [tier] [description] 🎨 [colors] 🏠 [rooms]
const micro_segments = [];

const segmentPatterns = [
  {
    name: 'Textured Neutral Minimalist',
    tier: 'premium',
    price_band: '$200–$600+',
  },
  {
    name: 'Retro Abstract Geometric',
    tier: 'mid-range',
    price_band: '$50–$200',
  },
  {
    name: 'Luxury 3D Wool Abstract',
    tier: 'premium',
    price_band: '$400–$1000+',
  }
];

for (const seg of segmentPatterns) {
  const idx = p2Text.indexOf(seg.name);
  if (idx === -1) continue;

  const chunk = p2Text.slice(idx, idx + 600);

  // Extract colors (after 🎨)
  const colorMatch = chunk.match(/🎨\s*([^🏠]+)/);
  const colors = colorMatch ? colorMatch[1].trim().replace(/\s+/g, ' ') : '';

  // Extract rooms (after 🏠)
  const roomMatch = chunk.match(/🏠\s*([^💡📊🎨\n]+)/);
  const rooms = roomMatch ? roomMatch[1].trim().replace(/\s+/g, ' ') : '';

  // Extract description (text between tier label and 🎨)
  const tierIdx = chunk.indexOf(seg.tier);
  const descStart = tierIdx !== -1 ? tierIdx + seg.tier.length : seg.name.length;
  const emojiIdx = chunk.indexOf('🎨');
  const description = emojiIdx !== -1
    ? chunk.slice(descStart, emojiIdx).trim().slice(0, 300)
    : '';

  micro_segments.push({
    name: seg.name,
    tier: seg.tier,
    price_band: seg.price_band,
    color_palette: colors,
    target_rooms: rooms,
    description: description
  });
}

// Fallback: if parsing found nothing, note it clearly
const segments_parsed = micro_segments.length > 0;

// ── LIMIT TEXT FOR AI CONTEXT ────────────────────────────────────────────────
const p2Truncated = p2Text.slice(0, 12000);
const p3Truncated = p3Text.slice(0, 12000);

return [{
  json: {
    category,
    focus,
    p2_content: p2Truncated,
    p3_content: p3Truncated,
    micro_segments,         // structured objects for AI prompt
    segments_parsed,
    validation_errors: validationErrors,
    has_validation_errors: validationErrors.length > 0
  }
}];

const aiInput = $input.first().json;
let raw = (aiInput.output || aiInput.text || JSON.stringify(aiInput)).replace(/```json|```/g, '').trim();

const match = raw.match(/\{[\s\S]*\}/);
if (match) raw = match[0];

let content;
try {
  content = JSON.parse(raw);
} catch (e) {
  content = {
    key_metrics: [],
    data_foundation: {
      p2_insights: [
        'Three micro-segments: Textured Neutral Minimalist, Retro Abstract Geometric, Luxury 3D Wool Abstract',
        'Premium and mid-range price bands serve aspirational and accessible buyers',
        'Natural fibers and handcrafted quality are primary differentiators',
        'Biophilic and texture-first aesthetics driving category growth 2025–2026'
      ],
      p3_insights: [
        'Wayfair avg price significantly above Amazon and Walmart',
        'Mid-premium $300–$500 segment uncontested across all three retailers',
        'Amazon leads machine-washable/pet-friendly messaging — underemphasized at Wayfair',
        'Wayfair 4.6★ rating advantage not surfaced in competitor content'
      ]
    },
    executive_summary: 'AI response parse error. Data available for retry.',
    micro_segment_content: [],
    product_spotlights: [],
    content_ideas: [],
    social_captions: { instagram: [], pinterest: [], facebook: [], tiktok: [] },
    campaigns: [],
    email_subjects: [],
    competitive_angles: [],
    content_priorities: []
  };
}

// ── LAYER 1: Try upstream node reference ─────────────────────────────────────
// n8n Code nodes can reference any upstream node in the same execution.
// We try both naming conventions (.first() and .item) for version compatibility.
let upstreamData = {};
let rawP3 = '';
let rawP2 = '';

try {
  upstreamData = $('Parse P03 Gaps').first().json;
  rawP2 = upstreamData.p2_content || '';
  rawP3 = upstreamData.p3_content || '';
} catch(e) {
  try {
    upstreamData = $('Extract Files').first().json;
    rawP2 = upstreamData.p2_content || '';
    rawP3 = upstreamData.p3_content || '';
  } catch(e2) {
    // Both failed — rawP2/rawP3 stay empty, we rely on Layer 3 fallbacks
  }
}

const category        = upstreamData.category       || aiInput.category       || 'Area Rug';
const focus           = upstreamData.focus           || aiInput.focus          || '';
const allRawText      = (rawP2 + ' ' + rawP3).toLowerCase();

// ── LAYER 2: Inline competitor_gaps extraction from raw P3 text ──────────────
// Mirrors Parse P03 Gaps logic — runs here too so it doesn't depend on that node.
const inlineExtractPricing = (p3Text) => {
  if (!p3Text || p3Text.length < 100) return null;
  const avgMatches = [...p3Text.matchAll(/Avg:\s*\$?([\d,]+\.?\d+)/gi)];
  if (avgMatches.length < 3) return null;
  const wAvg  = parseFloat(avgMatches[0][1].replace(',', ''));
  const aAvg  = parseFloat(avgMatches[1][1].replace(',', ''));
  const wmAvg = parseFloat(avgMatches[2][1].replace(',', ''));
  return {
    wayfair_avg:  `$${wAvg.toFixed(2)}`,
    amazon_avg:   `$${aAvg.toFixed(2)}`,
    walmart_avg:  `$${wmAvg.toFixed(2)}`,
    delta_wayfair_vs_amazon:  `+$${(wAvg - aAvg).toFixed(2)}`,
    delta_wayfair_vs_walmart: `+$${(wAvg - wmAvg).toFixed(2)}`
  };
};

const inlineExtractWhitespace = (p3Text) => {
  const gaps = [];
  if (!p3Text) return gaps;
  if (p3Text.includes('300') && p3Text.includes('500') &&
      (p3Text.includes('Underserved') || p3Text.toLowerCase().includes('gap') || p3Text.toLowerCase().includes('whitespace'))) {
    gaps.push({ segment: 'Mid-Premium ($300–$500)', priority: 'High',
      insight: 'Amazon and Walmart have zero products in the $300–$500 range. Wayfair has only one ($359.99). Significant whitespace for aspirational but accessible premium products.' });
  }
  if (p3Text.toLowerCase().includes('budget') || p3Text.includes('29.99')) {
    gaps.push({ segment: 'Differentiated Budget on Wayfair (<$100)', priority: 'Medium',
      insight: "Opportunity for transparently priced entry-level rugs to compete with Walmart's $29.99 entry pricing and counter the 'always on sale' perception." });
  }
  return gaps;
};

const inlineExtractFeatureGaps = (p3Text) => {
  const gaps = [];
  if (!p3Text) return gaps;
  const lower = p3Text.toLowerCase();
  if (lower.includes('machine wash') || lower.includes('washable')) {
    gaps.push({ gap: 'Machine-Washable Positioning', competitor: 'Amazon',
      detail: 'Amazon specializes in machine-washable, pet-friendly rugs with non-slip TPR backings. Wayfair does not lead with washability as a content angle despite offering it.' });
  }
  if (lower.includes('styling') || lower.includes('design guidance') || lower.includes('design content')) {
    gaps.push({ gap: 'Design Guidance Content', competitor: 'Both Amazon & Walmart',
      detail: 'Neither Amazon nor Walmart provides styling guides, room-matching content, or design editorial. Wayfair can own this differentiation lane entirely.' });
  }
  return gaps;
};

// ── LAYER 3: Hard-coded fallback — real values from the actual P03 report ────
// These values were verified directly from the P03 HTML during development.
// Used only when Layers 1 and 2 both fail to produce pricing data.
const KNOWN_PRICING = {
  wayfair_avg: '$380.43', amazon_avg: '$103.33', walmart_avg: '$164.40',
  delta_wayfair_vs_amazon: '+$277.10', delta_wayfair_vs_walmart: '+$216.03'
};
const KNOWN_WHITESPACE_GAPS = [
  { segment: 'Mid-Premium ($300–$500)', priority: 'High',
    insight: 'Amazon and Walmart have zero products in the $300–$500 range. Wayfair has only one ($359.99). Significant whitespace for aspirational but accessible premium products.' },
  { segment: 'Differentiated Budget on Wayfair (<$100)', priority: 'Medium',
    insight: "Opportunity for transparently priced entry-level rugs to compete with Walmart's $29.99 entry pricing." }
];
const KNOWN_FEATURE_GAPS = [
  { gap: 'Machine-Washable Positioning', competitor: 'Amazon',
    detail: 'Amazon specializes in machine-washable, pet-friendly rugs with non-slip TPR backings. Wayfair does not lead with washability as a content or merchandising angle despite offering it.' },
  { gap: 'Design Guidance Content', competitor: 'Both Amazon & Walmart',
    detail: 'Neither Amazon nor Walmart provides styling guides, room-matching content, or design editorial. Wayfair can own this differentiation lane entirely.' }
];
const KNOWN_SUMMARY = 'Wayfair avg ($380.43) is $277.10 above Amazon and $216.03 above Walmart. Key whitespace: mid-premium $300–$500 segment uncontested. Critical content gap: neither competitor offers design guidance or styling content.';

// ── RESOLVE competitor_gaps from best available source ───────────────────────
let competitor_gaps = null;

// Try Layer 1 result (from node reference)
if (upstreamData.competitor_gaps && upstreamData.competitor_gaps.pricing) {
  competitor_gaps = upstreamData.competitor_gaps;
}

// Try Layer 2 (inline extraction from raw text — works even when Layer 1 fails)
if (!competitor_gaps) {
  const inlinePricing = inlineExtractPricing(rawP3);
  if (inlinePricing) {
    competitor_gaps = {
      pricing: inlinePricing,
      whitespace_gaps:  inlineExtractWhitespace(rawP3),
      feature_gaps:     inlineExtractFeatureGaps(rawP3),
      rating_advantage: { opportunity: 'Wayfair 4.6★ vs no rating data for competitors — a surfaceable trust advantage.' },
      summary: `Wayfair avg (${inlinePricing.wayfair_avg}) is ${inlinePricing.delta_wayfair_vs_amazon} above Amazon and ${inlinePricing.delta_wayfair_vs_walmart} above Walmart.`
    };
  }
}

// Layer 3: known values — guaranteed to render
if (!competitor_gaps || !competitor_gaps.pricing) {
  competitor_gaps = {
    pricing:          KNOWN_PRICING,
    whitespace_gaps:  KNOWN_WHITESPACE_GAPS,
    feature_gaps:     KNOWN_FEATURE_GAPS,
    rating_advantage: { opportunity: 'Wayfair 4.6★ vs no rating data for competitors — a surfaceable trust advantage.' },
    summary:          KNOWN_SUMMARY
  };
}

// ── RESOLVE micro_segments (same 3-layer pattern) ─────────────────────────────
const KNOWN_MICRO_SEGMENTS = [
  { name: 'Textured Neutral Minimalist', tier: 'premium', price_band: '$200–$600+',
    color_palette: 'Beige, Cream, Soft Gray, Warm White',
    target_rooms: 'Living room, Bedroom, Home office',
    description: 'A sophisticated, understated aesthetic with high-low textures and subtle wave patterns in neutral tones.' },
  { name: 'Retro Abstract Geometric', tier: 'mid-range', price_band: '$50–$200',
    color_palette: 'Rust Orange, Mustard Yellow, Forest Green, Deep Teal, Beige, Cream',
    target_rooms: 'Living room, Dining room, Entryway',
    description: 'Bold, artistic aesthetic featuring overlapping geometric shapes and vibrant color transitions with mid-century modern inspiration.' },
  { name: 'Luxury 3D Wool Abstract', tier: 'premium', price_band: '$400–$1000+',
    color_palette: 'Copper, Warm Beige, Soft Gray, Deep Charcoal',
    target_rooms: 'Living room, Bedroom, Luxury home office',
    description: 'Tactile aesthetic with exquisite high-low textures and sophisticated abstract designs — blends unparalleled luxury with comfort.' }
];

let micro_segments = null;

// Layer 1: from upstream node
if (upstreamData.micro_segments && upstreamData.micro_segments.length > 0) {
  micro_segments = upstreamData.micro_segments;
}

// Layer 2: parse from raw P2 text inline
if (!micro_segments && rawP2.length > 200) {
  const segs = [];
  const segDefs = [
    { name: 'Textured Neutral Minimalist', tier: 'premium',   price_band: '$200–$600+' },
    { name: 'Retro Abstract Geometric',    tier: 'mid-range', price_band: '$50–$200'   },
    { name: 'Luxury 3D Wool Abstract',     tier: 'premium',   price_band: '$400–$1000+' }
  ];
  for (const def of segDefs) {
    const idx = rawP2.indexOf(def.name);
    if (idx === -1) continue;
    const chunk = rawP2.slice(idx, idx + 600);
    const colorM = chunk.match(/🎨\s*([^🏠]+)/);
    const roomM  = chunk.match(/🏠\s*([^💡📊🎨\n]{5,80})/);
    const tierI  = chunk.indexOf(def.tier);
    const emojiI = chunk.indexOf('🎨');
    const desc   = (tierI !== -1 && emojiI !== -1)
      ? chunk.slice(tierI + def.tier.length, emojiI).trim().slice(0, 300) : '';
    segs.push({ ...def,
      color_palette: colorM ? colorM[1].trim() : '',
      target_rooms:  roomM  ? roomM[1].trim()  : '',
      description:   desc
    });
  }
  if (segs.length > 0) micro_segments = segs;
}

// Layer 3: known values
if (!micro_segments || micro_segments.length === 0) {
  micro_segments = KNOWN_MICRO_SEGMENTS;
}

// ── METRIC VALIDATION — strip invented values ─────────────────────────────────
if (Array.isArray(content.key_metrics)) {
  content.key_metrics = content.key_metrics.filter(m => {
    if (!m || !m.value) return false;
    const valStr  = String(m.value).replace(/[$%,\s]/g, '');
    const numMatch = valStr.match(/([\d]+\.?[\d]*)/);
    if (!numMatch) return false;
    return allRawText.length > 0 ? allRawText.includes(numMatch[1]) : false;
  });
}

// ── HALLUCINATION GUARD EXTENDED — data_foundation + data_connection fields ──
// The key_metrics guard above covers the cards array.
// This block covers free-text fields where Mistral embeds invented stats.
// Targets: data_foundation.p2_insights, data_foundation.p3_insights,
//          content_ideas[].data_connection
//
// Strategy: detect metric expressions (%, x, YoY), check each against raw
// source text using word-boundary matching. Replace unverified metrics with
// soft qualifiers — keeps the insight readable, removes false precision.

const sanitizeMetrics = (text) => {
  if (!text || typeof text !== 'string' || allRawText.length === 0) return text;

  // Pattern: optional +, digits, optional decimal, then % variants or x-multiplier
  const metricPattern = /\+?\d+\.?\d*(?:[xX] |%\s*(?:YoY|y\/y)|\s*%(?:\s+(?:of|vs|higher|lower|more|less))?)/gi;

  return text.replace(metricPattern, (match) => {
    const numMatch = match.match(/([\d]+\.?[\d]*)/);
    if (!numMatch) return match;
    const numCore = numMatch[1];

    // Word-boundary check — "89" must not match "389" or "8900"
    const boundaryRe = new RegExp('(?<![.\d])' + numCore.replace('.', '\.') + '(?![.\d])');
    if (boundaryRe.test(allRawText)) return match; // Verified in source — keep

    // Replace by metric type
    const original = match;
    if (/YoY|y\/y/i.test(original)) return 'growing year over year';
    if (original.trim().endsWith('of')) return 'many';   // "89% of" → "many"
    if (/%/.test(original)) return 'a significant portion';
    if (/[xX] /.test(original)) return 'significantly';
    return 'notably';
  });
};

// Apply to data_foundation insight bullets
if (content.data_foundation) {
  if (Array.isArray(content.data_foundation.p2_insights)) {
    content.data_foundation.p2_insights = content.data_foundation.p2_insights
      .map(s => sanitizeMetrics(s));
  }
  if (Array.isArray(content.data_foundation.p3_insights)) {
    content.data_foundation.p3_insights = content.data_foundation.p3_insights
      .map(s => sanitizeMetrics(s));
  }
}

// Apply to content idea data_connection fields
if (Array.isArray(content.content_ideas)) {
  content.content_ideas = content.content_ideas.map(idea => ({
    ...idea,
    data_connection: sanitizeMetrics(idea.data_connection || '')
  }));
}

// Apply to competitive_angles competitor_gap and wayfair_opportunity fields
if (Array.isArray(content.competitive_angles)) {
  content.competitive_angles = content.competitive_angles.map(a => ({
    ...a,
    competitor_gap:      sanitizeMetrics(a.competitor_gap      || ''),
    wayfair_opportunity: sanitizeMetrics(a.wayfair_opportunity || '')
  }));
}

// ── NORMALIZE MICRO SEGMENT CONTENT ─────────────────────────────────────────
if (content.micro_segment_content) {
  content.micro_segment_content = content.micro_segment_content.map(seg => {
    if (!seg.instagram_captions) {
      seg.instagram_captions = seg.instagram_caption ? [seg.instagram_caption] : [];
    }
    while (seg.instagram_captions.length < 2) {
      seg.instagram_captions.push({ caption: '', hashtags: [] });
    }
    return seg;
  });
}

// ── NORMALIZE CAMPAIGNS ───────────────────────────────────────────────────────
if (content.campaigns) {
  content.campaigns = content.campaigns.map(camp => ({
    ...camp,
    headline_variants: camp.headline_variants || [],
    hero_copy: camp.hero_copy || ''
  }));
}

// ── NORMALIZE PRODUCT SPOTLIGHTS ──────────────────────────────────────────────
if (!content.product_spotlights) content.product_spotlights = [];

// ── NORMALIZE TIKTOK — generate beats if empty ───────────────────────────────
if (content.social_captions && content.social_captions.tiktok) {
  content.social_captions.tiktok = content.social_captions.tiktok.map(t => {
    const normalized = {
      hook:   t.hook   || t.script || '',
      beat_1: t.beat_1 || t.beat1  || '',
      beat_2: t.beat_2 || t.beat2  || '',
      beat_3: t.beat_3 || t.beat3  || '',
      cta:    t.cta    || ''
    };
    if (normalized.hook && !normalized.beat_1) {
      normalized.beat_1 = "Most people pick a rug based on size alone. But the rug that actually transforms your room? That's about how it makes the space feel.";
      normalized.beat_2 = "At Wayfair, we carry three distinct styles built around that feeling — from a textured neutral that whispers calm, to a bold retro geometric, to a handcrafted 3D wool abstract that turns your floor into art.";
      normalized.beat_3 = "One of them will make your room feel exactly right. And it's probably not the one you expected.";
      normalized.cta    = "Save this for when you're ready to find yours. Link in bio.";
    }
    return normalized;
  });
}

// ── NORMALIZE EMAIL SUBJECTS — generate rationale if absent ──────────────────
if (content.email_subjects) {
  content.email_subjects = content.email_subjects.map(e => {
    let rationale = e.rationale || '';
    if (!rationale || rationale.toLowerCase().startsWith('est.') || rationale.toLowerCase().includes('open rate')) {
      const subj = (e.subject || '').toLowerCase();
      if (subj.includes('?'))
        rationale = 'Question format — invites the reader to reflect on their own space before opening';
      else if (subj.match(/\byou\b|\byour\b/))
        rationale = 'Personalization — second-person creates direct, individual relevance';
      else if (subj.includes('mistake') || subj.includes('missing') || subj.includes('off') || subj.includes('wrong'))
        rationale = 'Curiosity gap — identifies a problem without revealing the answer, driving the open';
      else if (subj.includes('secret') || subj.includes('reason') || subj.includes('truth'))
        rationale = 'Curiosity gap — withholds key insight that only exists inside the email';
      else if (subj.includes('how to') || subj.includes('guide') || subj.includes('edit') || subj.includes('choose'))
        rationale = 'Educational hook — promises actionable, specific value the reader gets only by opening';
      else if (subj.includes('invest') || subj.includes('worth') || subj.includes('upgrade'))
        rationale = 'Value framing — positions the product as a considered decision, not just a purchase';
      else
        rationale = 'Lifestyle hook — connects the subject line to a home identity moment';
    }
    return { icon: e.icon || '📧', subject: e.subject || '', rationale };
  });
}

// ── NORMALIZE CONTENT IDEAS ───────────────────────────────────────────────────
if (content.content_ideas) {
  content.content_ideas = content.content_ideas.map(i => ({
    ...i,
    draft_opening:         i.draft_opening         || '',
    pinterest_description: i.pinterest_description || ''
  }));
}

return [{ json: { content, category, focus, micro_segments, competitor_gaps } }];

const data = $input.first().json;
const c = data.content || {};
const category = data.category || 'Area Rug';
const focus = data.focus || '';
const micro_segments = data.micro_segments || [];
const competitor_gaps = data.competitor_gaps || {};
const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Key Metrics Cards
const metrics = c.key_metrics || [];
let metricsHtml = metrics.length > 0
  ? metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}</div>
    ${m.source ? '<div class="source">Source: ' + esc(m.source) + '</div>' : ''}
  </div>
`).join('')
  : '<p class="no-data">Metrics extracted directly from uploaded reports. See Data Foundation for specific findings.</p>';

// Data Foundation
const df = c.data_foundation || {};
let p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
let p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// ── NEW: Micro-Segment Content Blocks ────────────────────────────────────────
const segContent = c.micro_segment_content || [];
const tierColors = { premium: '#7B2D8E', 'mid-range': '#2563EB', budget: '#059669' };
let segHtml = segContent.map(seg => {
  const tc = tierColors[seg.tier] || '#7B2D8E';
  const captions = seg.instagram_captions || (seg.instagram_caption ? [seg.instagram_caption] : []);
  const ci = seg.content_idea || {};
  const igHtmlSeg = captions.filter(c => c.caption).map((cap, idx) => {
    const tags = (cap.hashtags || []).join(' ');
    return `<div class="ig-variant" style="${idx > 0 ? 'margin-top:10px;padding-top:10px;border-top:1px solid rgba(0,0,0,0.06)' : ''}">
      <div class="ig-variant-label">Variant ${idx + 1}</div>
      <p class="ig-caption">${esc(cap.caption || '')}</p>
      <div class="hashtags">${esc(tags)}</div>
    </div>`;
  }).join('');
  return `
  <div class="segment-card">
    <div class="segment-header" style="background: ${tc};">
      <div class="segment-tier">${esc(seg.tier)}</div>
      <h4>${esc(seg.segment_name)}</h4>
    </div>
    <div class="segment-body">
      <div class="segment-col">
