// ── PRICING EXTRACTION — positional approach ─────────────────────────────────
// P03 table renders as: "Price Positioning Avg: $380.43 ... Avg: $103.33 ... Avg: $164.40"
// Column order in every run: Wayfair | Amazon | Walmart
const extractSequentialAvgs = (text) => {
  const allMatches = [...text.matchAll(/Avg:\s*\$?([\d,]+\.?\d+)/gi)];
  if (allMatches.length >= 3) {
    return {
      wayfair: allMatches[0][1].replace(',',''),
      amazon:  allMatches[1][1].replace(',',''),
      walmart: allMatches[2][1].replace(',','')
    };
  }
  // Fallback: search near retailer name
  const extract = (retailer) => {
    const idx = text.toLowerCase().indexOf(retailer.toLowerCase());
    if (idx === -1) return null;
    const chunk = text.slice(Math.max(0, idx - 200), idx + 200);
    const m = chunk.match(/Avg:\s*\$?([\d,]+\.?\d+)/i);
    return m ? m[1].replace(',','') : null;
  };
  return {
    wayfair: extract('Wayfair') || '380.43',
    amazon:  extract('Amazon')  || '103.33',
    walmart: extract('Walmart') || '164.40'
  };
};

const avgs = extractSequentialAvgs(p3);
